<?php
declare(strict_types=1);
namespace MiniErp\Fiscal;
use MiniErp\Contracts\TaxRuleRepositoryContract; use RuntimeException;
final readonly class TaxRuleResolver { public function __construct(private TaxRuleRepositoryContract $rules){} public function resolve(FiscalTaxContext $context):FiscalTaxResolution{$matches=array_values(array_filter($this->rules->findCandidates($context),fn(FiscalTaxRule $r):bool=>$r->matches($context)));if($matches===[]){$candidate=$context->cfopHint?:'não definido';throw new RuntimeException("Não existe regra tributária configurada para NCM {$context->ncm}, CRT {$context->crt} e operação {$context->direction}. CFOP candidato: {$candidate}.");}usort($matches,function(FiscalTaxRule $a,FiscalTaxRule $b):int{$fallback=($a->fixtureKind==='CONFIGURATION_FALLBACK'?1:0)<=>($b->fixtureKind==='CONFIGURATION_FALLBACK'?1:0);return$fallback!==0?$fallback:([$b->priority,$b->specificity(),$b->validFrom->getTimestamp()]<=>[$a->priority,$a->specificity(),$a->validFrom->getTimestamp()]);});$winner=$matches[0];if(isset($matches[1])&&$winner->fixtureKind!=='CONFIGURATION_FALLBACK'&&$matches[1]->fixtureKind!=='CONFIGURATION_FALLBACK'&&$winner->priority===$matches[1]->priority&&$winner->specificity()===$matches[1]->specificity()&&$winner->validFrom==$matches[1]->validFrom)throw new RuntimeException('More than one fiscal rule matches this operation.');return FiscalTaxResolution::fromRule($winner);} }
